/*
 * A135312  Number of transitive reflexive binary relations R on n labeled
 *          elements where |{y : xRy}| <= 2 for all x.
 * https://oeis.org/A135312
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 7, u32 n <= 13, u64 n <= 22, u128 n <= 37,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A135312:  a(n) = Sum_{i=0..⌊n/2⌋} C(n,2i) * A006882(2i-1) * A000248(n-2i)
 *  The sequence may be generated by the recurrence
 *      a(0) = 1
 *      a(n) = Σ_{k=1..n} C(n-1,k-1) * a(n-k) * t_k          (n ≥ 1)
 *  where t_k = 1 (k=1), 3 (k=2), and t_k = k (k ≥ 3).
 */
#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Static cache for previously computed terms. */
    static seq_t *cache = NULL;
    static idx_t last_cached = 0;   /* highest n that has been computed */

    /* Initialise cache for the first call. */
    if (cache == NULL) {
        cache = (seq_t *)malloc((n + 1) * sizeof(seq_t));
        if (cache == NULL) return 0; /* allocation failure */
        cache[0] = 1;                /* a(0) = 1 */
        last_cached = 0;
    }

    /* Grow cache if the requested n is beyond the current maximum. */
    if (n > last_cached) {
        seq_t *new_cache = (seq_t *)realloc(cache, (n + 1) * sizeof(seq_t));
        if (new_cache == NULL) return 0; /* allocation failure */
        cache = new_cache;

        /* Compute missing terms from last_cached+1 up to n. */
        for (idx_t m = last_cached + 1; m <= n; ++m) {
            seq_t sum = 0;
            seq_t bin = 1;                /* C(m-1,0) */
            for (idx_t k = 0; k <= m - 1; ++k) {
                idx_t j = k + 1;          /* the current k in the recurrence */
                seq_t t;
                if (j == 1)
                    t = 1;
                else if (j == 2)
                    t = 3;
                else
                    t = (seq_t)j;

                /* term = C(m-1,k) * t * a(m-k-1) */
                seq_t term = bin * t * cache[m - 1 - k];
                sum = sum + term;

                /* Update binomial coefficient for the next k. */
                if (k < m - 1) {
                    seq_t num = (seq_t)(m - 1 - k);
                    seq_t den = (seq_t)(k + 1);
                    bin = bin * num / den;   /* exact division */
                }
            }
            cache[m] = sum;
        }
        last_cached = n;
    }

    return cache[n];
}
